/*
 Problem: 835. Image Overlap
 Language: cpp
 Runtime: 31 ms (63.76%)
 Memory: 16.4 MB (5.63%)
 Tags: Array, Matrix
*/
class Solution {
public:
    int largestOverlap(vector<vector<int>>& img1, vector<vector<int>>& img2) {
        int n = img1.size();

        vector<pair<int, int>> a;
        vector<pair<int, int>> b;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {

                if (img1[i][j] == 1)
                    a.push_back({i, j});

                if (img2[i][j] == 1)
                    b.push_back({i, j});
            }
        }

        unordered_map<long long, int> mp;

        int ans = 0;

        for (auto [r1, c1] : a) {
            for (auto [r2, c2] : b) {

                int dr = r2 - r1;
                int dc = c2 - c1;

                long long key =
                    (long long)(dr + n) * (2 * n + 1)
                    + (dc + n);

                mp[key]++;

                ans = max(ans, mp[key]);
            }
        }

        return ans;
    }
};
